insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-01','TWK','TWK-9dc76c12b13d','Nilai yang hidup dalam keputusan sehari-hari','Pancasila menjadi dasar negara dan pedoman nilai. Kelima silanya saling berkaitan; contoh kasus dapat melibatkan beberapa sila sekaligus.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-02','TWK','TWK-d0d43d059432','Mengenal UUD NRI Tahun 1945','UUD NRI Tahun 1945 adalah konstitusi Indonesia. Gunakan naskah resmi untuk membaca pasal beserta perubahan-perubahannya.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-03','TWK','TWK-a9c6ce185579','Persatuan yang menghormati keragaman','Nasionalisme diwujudkan dengan kontribusi yang jujur, penghormatan keragaman, dan kepentingan bersama.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-04','TWK','TWK-29f3826a97ff','Tanggung jawab warga di ruang nyata dan digital','Bela negara tidak terbatas pada kegiatan militer. Warga dapat berkontribusi sesuai kemampuan dan profesi.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-05','TIU','TIU-f86dbe9cf536','Membaca pola sebelum menghitung','Cari selisih antarangka terlebih dahulu. Deret aritmetika memiliki selisih tetap; deret geometri memiliki rasio tetap.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-06','TIU','TIU-8bc026d24168','Persentase, rasio, dan ketelitian satuan','Persen berarti per seratus. Diskon p% menghasilkan harga akhir = harga awal × (100 − p)/100.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-07','TIU','TIU-a901cfd0fdee','Memisahkan variabel secara bertahap','Persamaan tetap seimbang bila operasi yang sama diterapkan pada kedua ruas.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-08','TIU','TIU-72fc6fb57fea','Pola bentuk dan siklus visual','Amati jumlah, posisi, arah, bentuk, dan pola pengulangan. Analisis satu atribut setiap kali.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-09','TKP','TKP-5c69364df647','Respons yang membantu dan dapat dipertanggungjawabkan','Pelayanan yang baik memadukan empati, kejelasan informasi, ketepatan prosedur, dan tindak lanjut.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-10','TKP','TKP-c540e14e524e','Jujur saat keputusan terasa sulit','Integritas berarti konsisten antara nilai, ucapan, dan tindakan. Dokumentasi membantu menjaga akuntabilitas.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-11','TKP','TKP-aac612241dac','Layanan aman di lingkungan digital','Gunakan akses minimum yang diperlukan dan lindungi kata sandi serta OTP.
insert into lessons(id,domain,topic_id,title,body_md,duration,version,reviewer,review_status,publication_status) values('lesson-12','TKP','TKP-c8ea45d70415','Kolaborasi yang jelas dan inklusif','Kolaborasi efektif memerlukan tujuan, peran, tenggat, dan jalur komunikasi yang jelas.
